CREATE TABLE IF NOT EXISTS "bpm_user_group" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name" varchar(63) NOT NULL,
    "description" varchar(255) NOT NULL,
    "status" tinyint NOT NULL,
    "user_ids" varchar(255) NOT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
) COMMENT '用户组';

CREATE TABLE IF NOT EXISTS "bpm_category" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name" varchar(63) NOT NULL,
    "code" varchar(63) NOT NULL,
    "description" varchar(255) NOT NULL,
    "status" tinyint NOT NULL,
    "sort" int NOT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
) COMMENT '分类';

CREATE TABLE IF NOT EXISTS "bpm_form" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name" varchar(63) NOT NULL,
    "status" tinyint NOT NULL,
    "fields" varchar(255) NOT NULL,
    "conf" varchar(255) NOT NULL,
    "remark" varchar(255),
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
) COMMENT '动态表单';

CREATE TABLE IF NOT EXISTS "bpm_instance_participant" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "process_instance_id" varchar(64) NOT NULL DEFAULT '',
    "root_process_instance_id" varchar(64) NOT NULL DEFAULT '',
    "parent_process_instance_id" varchar(64) DEFAULT NULL,
    "form_code" varchar(64) DEFAULT NULL,
    "business_key" varchar(64) DEFAULT NULL,
    "user_id" bigint NOT NULL DEFAULT 0,
    "participation" tinyint NOT NULL DEFAULT 0,
    "task_id" varchar(64) DEFAULT NULL,
    "activity_id" varchar(64) DEFAULT NULL,
    "writable" bit NOT NULL DEFAULT FALSE,
    "start_time" timestamp DEFAULT NULL,
    "end_time" timestamp DEFAULT NULL,
    "retain_until" timestamp DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT '流程实例参与人';

CREATE TABLE IF NOT EXISTS "bpm_instance_participant_archive" (
    "id" bigint NOT NULL,
    "process_instance_id" varchar(64) NOT NULL DEFAULT '',
    "root_process_instance_id" varchar(64) DEFAULT NULL,
    "parent_process_instance_id" varchar(64) DEFAULT NULL,
    "form_code" varchar(64) DEFAULT NULL,
    "business_key" varchar(64) DEFAULT NULL,
    "user_id" bigint NOT NULL DEFAULT 0,
    "participation" tinyint NOT NULL DEFAULT 0,
    "task_id" varchar(64) DEFAULT NULL,
    "activity_id" varchar(64) DEFAULT NULL,
    "writable" bit DEFAULT FALSE,
    "start_time" timestamp DEFAULT NULL,
    "end_time" timestamp DEFAULT NULL,
    "retain_until" timestamp DEFAULT NULL,
    "archived_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT '流程实例参与人（归档）';

CREATE TABLE IF NOT EXISTS "bpm_task_candidate_snapshot" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "process_instance_id" varchar(64) NOT NULL DEFAULT '',
    "task_id" varchar(64) DEFAULT NULL,
    "activity_id" varchar(64) DEFAULT NULL,
    "strategy" tinyint DEFAULT NULL,
    "param" varchar(512) DEFAULT NULL,
    "subject_type" varchar(16) DEFAULT NULL,
    "subject_ref_id" bigint DEFAULT NULL,
    "resolved_user_id" bigint NOT NULL DEFAULT 0,
    "snapshot_time" timestamp DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT '任务候选人快照';

CREATE TABLE IF NOT EXISTS "bpm_delegation" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "delegator_user_id" bigint NOT NULL DEFAULT 0,
    "delegate_user_id" bigint NOT NULL DEFAULT 0,
    "start_time" timestamp DEFAULT NULL,
    "end_time" timestamp DEFAULT NULL,
    "process_definition_keys" varchar(512) DEFAULT NULL,
    "reason" varchar(256) DEFAULT NULL,
    "status" tinyint NOT NULL DEFAULT 0,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT '流程委托';
